import codecs
for handler in ('strict', 'ignore', 'replace', 'backslashreplace', 'xmlcharrefreplace', 'namereplace', 'surrogatepass', 'surrogateescape'):
    for kind in ('encode', 'decode', 'translate'):
        for text in ('', 'a', chr(0xd800), chr(0xdc80), 'a' + chr(0xd800) + chr(0xdc80) + 'z', chr(0x1f40d)):
            for start, end in ((-3, -2), (-1, 0), (0, 0), (0, 1), (1, 1), (4, 2), (10, 20)):
                if kind == 'encode':
                    error = UnicodeEncodeError('utf-8', text, start, end, 'reason')
                elif kind == 'decode':
                    error = UnicodeDecodeError('utf-8', text.encode('utf-8', 'surrogatepass'), start, end, 'reason')
                else:
                    error = UnicodeTranslateError(text, start, end, 'reason')
                try:
                    result = codecs.lookup_error(handler)(error)
                    print(repr((handler, kind, text, start, end, 'ok', result)))
                except BaseException as failure:
                    print(repr((handler, kind, text, start, end, type(failure).__name__, failure.args)))
